import { betterAuth } from "better-auth";
import { prismaAdapter } from "better-auth/adapters/prisma";
import { PrismaClient } from "../generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import { betterAuthOptions } from "./options"
import type { Context } from "hono";
import extendedAttributes from "./extendedAttributes";
import plugins from "./plugins";
import hooks from "./hooks"

// @ts-expect-error
import { argon2id, argon2Verify, setWASMModules } from 'argon2-wasm-edge';
// @ts-expect-error
import argon2WASM from 'argon2-wasm-edge/wasm/argon2.wasm'; // <-- imports of wasm modules works differently in CF
// @ts-expect-error
import blake2bWASM from 'argon2-wasm-edge/wasm/blake2b.wasm';


import crypto from "crypto";
import resend from "../lib/email-verification";

setWASMModules({argon2WASM, blake2bWASM});

// If your Prisma file is located elsewhere, you can change the path
export function  createDb(c: Context) {
	const adapter = new PrismaPg({connectionString: c.env.HYPERDRIVE.connectionString});
	const prisma = new PrismaClient({adapter});
	return prisma;
}

const SITE_URL = 'http://localhost:3000';

export const auth = (prisma: PrismaClient) => betterAuth({
		...betterAuthOptions,
		...extendedAttributes,
		...plugins,
		...hooks,
		database: prismaAdapter(prisma, {
						provider: "postgresql", // or "mysql", "postgresql", ...etc
			}),
			emailAndPassword: {
				enabled: true,
				revokeSessionsOnPasswordReset: true,
				advanced: {
					disableOriginCheck: true,
					defaultCookieAttributes: {
						sameSite: 'none',
						httpOnly: true
					}
				},
				password: {
					hash: async (password) => {
              // the password after hashing e.g. const passwordHash = await hash(password);
							try {
								const salt = crypto.randomBytes(16);
              	const passwordHash = await argon2id({
									password: password,
									salt,
									parallelism: 1,
									iterations: 128,
									memorySize: 512,
									hashLength: 16,
									outputType: "encoded"
								});
								return passwordHash; // this is what will be stored as the password hash
							} catch(_e) {
								throw _e;
							}

            },
					verify: async ({hash, password}) => {
						const isValid = await argon2Verify({password, hash});
						if (!isValid)
							console.error("Wrong Password");
						return isValid
					}
				},


				sendResetPassword: async ({user, url, token}, request) => {
					resend.emails.send({
							from: `Rimborso.eu <noreply@verify.rimborso.eu>`,
							to: user.email,
							subject: 'Rimborso.eu - Reset Password',
							html: `Fai click sul link per eseguire il reset password: <a href='${url}'>verifica email</a>
							<br/><br/>
							Copia e incolla questo link sulla barra di ricerca se il bottone non dovesse funzionare ${url}`
					});
				},
				onPasswordReset: async ({ user }, request) => {
					// your logic here
					console.log(`Password for user ${user.email} has been reset.`);
				},
			},
			trustedOrigins: ['http://localhost:3000', 'https://rimborso.eu', 'https://www.rimborso.eu', "https://studiolegalefrisani.com", 'https://www.studiolegalefrisani.com', 'https://www.gestionecreditipubblici.it', 'https://gestionecreditipubblici.it', 'http://localhos:8787', 'https://dbapi.studiolegalefrisani.com', 'rimborsoeu-git-git-test-devgeecps-projects.vercel.app'],
			baseURL: {
				allowedHosts: [
				"localhost:3000",
				"*.rimborso.eu",
				"*.studiolegalefrisani.com",
				"*.gestionecreditipubblici.it",
				"db-rimborsoeu-worker.muddy-glade-5e96.workers.dev",
				"dbapi.studiolegalefrisani.com",
				"localhost:8787",
				"rimborsoeu-git-git-test-devgeecps-projects.vercel.app"
				],
				protocol: process.env.IS_DEV ? "http" : "https"
			},
			secret: process.env.BETTER_AUTH_SECRET,


			emailVerification: {
				sendVerificationEmail: async ({user, url, token}) => {
					const id = setTimeout(async () => {
						const userEntry = await prisma.user.findUnique({where: {email: user.email}});
						if (!userEntry)
						{
							console.log("User not found");
							return;
						}
							await resend.emails.send({
							from: `Rimborso.eu <noreply@verify.rimborso.eu>`,
							to: userEntry.email,
							subject: 'Conferma il tuo indirizzo email',
							html: `Fai click sul link per confermare il tuo indirizzo email: <a href='${SITE_URL}/mail-verified?token=${token}'>verifica email</a>
							<br/><br/>
							Copia e incolla questo link sulla barra di ricerca se il bottone non dovesse funzionare ${SITE_URL}/mail-verified?token=${token}`
						});
						console.log("inside timeout");
					}, 18000)
				},
			}
	});


